entries.body:
{
	"$schema": "https://json-schema.org/draft/2020-12/schema",
	"$id": "https://info.glyphsapp.com/schema/fontinfo-4.schema.json",
	"title": "Glyphs Document",
	"description": "A native Glyphs source file.",
	"type": "object",
	"$defs": {
		"anchor": {
			"type": "object",
			"properties": {
				"attr": {
					"$ref": "#/$defs/attr",
					"default": {},
					"description": "The attributes of the anchor.",
					"glyphsCondition": {
						"minVersion": 4
					}
				},
				"locked": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the anchor is locked.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"name": {
					"type": "string",
					"description": "The name of the anchor."
				},
				"orientation": {
					"$ref": "#/$defs/orientation",
					"default": "left",
					"description": "The orientation of the anchor.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"pos": {
					"$ref": "#/$defs/pos",
					"default": [
						0,
						0
					],
					"description": "The position of the anchor.",
					"glyphsCondition": {
						"minVersion": 3
					}
				}
			},
			"additionalProperties": false,
			"required": [
				"name"
			],
			"glyphsType": "GSAnchor"
		},
		"annotation": {
			"type": "object",
			"properties": {
				"angle": {
					"type": "number",
					"glyphsNumber": "f64",
					"default": 0,
					"description": "The angle of the annotation in degrees clockwise."
				},
				"pos": {
					"$ref": "#/$defs/pos",
					"default": [
						0,
						0
					],
					"description": "The position of the annotation.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"text": {
					"type": "string",
					"default": "",
					"description": "The text of a text-type annotation."
				},
				"type": {
					"enum": [
						"Text",
						"Arrow",
						"Circle",
						"Plus",
						"Minus"
					],
					"type": "string",
					"description": "The type of the annotation."
				},
				"width": {
					"type": "number",
					"glyphsNumber": "f64",
					"default": 0,
					"description": "The width of a text- or circle-type annotation."
				}
			},
			"additionalProperties": false,
			"required": [
				"type"
			],
			"glyphsType": "GSAnnotation"
		},
		"attr": {
			"type": "object",
			"additionalProperties": {}
		},
		"axis": {
			"type": "object",
			"properties": {
				"default": {
					"type": "number",
					"glyphsNumber": "f64",
					"default": 0,
					"description": "The default location on the axis."
				},
				"hidden": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the axis is considered to be hidden from the font user."
				},
				"name": {
					"type": "string",
					"default": "",
					"description": "The user-facing name of the axis."
				},
				"names": {
					"type": "array",
					"items": {
						"$ref": "#/$defs/infoValue"
					},
					"default": [],
					"description": "The user-facing, localized name of the axis.",
					"glyphsCondition": {
						"minVersion": 4
					}
				},
				"tag": {
					"type": "string",
					"default": "",
					"description": "The OpenType tag of the axis. Must be unique within the font. The tag may be longer than four characters in which case only the first four characters are considered to be the canonical tag of the axis and the rest is used as a differentiating identifier. On export, the canonical tag is used. Multiple axes with the same canonical tag are useful for higher-order interpolation."
				},
				"userData": {
					"$ref": "#/$defs/userData",
					"default": {},
					"description": "Custom data associated with the axis.",
					"glyphsCondition": {
						"minVersion": 4
					}
				}
			},
			"additionalProperties": false,
			"glyphsType": "GSAxis"
		},
		"class": {
			"type": "object",
			"properties": {
				"automatic": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the code of the class is generated automatically."
				},
				"disabled": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the class is disabled."
				},
				"file": {
					"type": "string",
					"description": "The file name of the file containing the code of the class. The file is located in `DocumentName.glyphspackage/features/FILENAME` where `FILENAME` is this value. The file contents are equivalent to the string defined by the `code` property.",
					"glyphsCondition": {
						"regular": false,
						"package": {
							"minVersion": 4
						}
					}
				},
				"name": {
					"type": "string",
					"examples": [
						"Uppercase",
						"CombiningTopAccents"
					],
					"description": "The name of the class. The leading at sign (`@`) is not included."
				},
				"notes": {
					"type": "string",
					"default": "",
					"description": "A string serving as a description or comment about the class."
				}
			},
			"additionalProperties": false,
			"required": [
				"name"
			],
			"glyphsType": "GSClass"
		},
		"color": {
			"oneOf": [
				{
					"type": "array",
					"prefixItems": [
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The red color component.",
							"minimum": 0,
							"maximum": 1
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The green color component.",
							"minimum": 0,
							"maximum": 1
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The blue color component.",
							"minimum": 0,
							"maximum": 1
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The alpha color component.",
							"minimum": 0,
							"maximum": 1
						}
					],
					"items": false,
					"minItems": 4,
					"maxItems": 4,
					"glyphsCompact": true,
					"description": "An RGB color with an alpha channel in the font color space. In version 4, color components are normalized to the range 0\u20261.",
					"glyphsCondition": {
						"minVersion": 4
					}
				},
				{
					"type": "array",
					"prefixItems": [
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The gray value from `0` (black) to `1` (white).",
							"minimum": 0,
							"maximum": 1
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The alpha color component.",
							"minimum": 0,
							"maximum": 1
						}
					],
					"items": false,
					"minItems": 2,
					"maxItems": 2,
					"glyphsCompact": true,
					"description": "A gray color with an alpha channel. In version 4, color components are normalized to the range 0\u20261.",
					"glyphsCondition": {
						"minVersion": 4
					}
				},
				{
					"type": "array",
					"prefixItems": [
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The cyan color component.",
							"minimum": 0,
							"maximum": 1
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The magenta color component.",
							"minimum": 0,
							"maximum": 1
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The yellow color component.",
							"minimum": 0,
							"maximum": 1
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The black color component.",
							"minimum": 0,
							"maximum": 1
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"description": "The alpha color component.",
							"minimum": 0,
							"maximum": 1
						}
					],
					"items": false,
					"minItems": 5,
					"maxItems": 5,
					"glyphsCompact": true,
					"description": "A CMYK color with an alpha channel. In version 4, color components are normalized to the range 0\u20261.",
					"glyphsCondition": {
						"minVersion": 4
					}
				},
				{
					"type": "array",
					"prefixItems": [
						{
							"type": "string",
							"const": "p",
							"description": "Indicates a palette color reference."
						},
						{
							"type": "integer",
							"glyphsNumber": "u16",
							"minimum": 0,
							"maximum": 65535,
							"description": "The color palette entry index. `65535` indicates the current text color."
						},
						{
							"type": "number",
							"glyphsNumber": "f64",
							"minimum": 0,
							"maximum": 1,
							"default": 1,
							"description": "The alpha factor applied to the referenced palette color."
						}
					],
					"items": false,
					"minItems": 3,
					"maxItems": 3,
					"glyphsCompact": true,
					"description": "A color reference into the `Color Palettes` custom parameter.",
					"glyphsCondition": {
						"minVersion": 4
					}
				}
			]
		},
		"colorLabel": {
			"oneOf": [
				{
					"type": "integer",
					"glyphsNumber": "u8",
					"description": "The index of the color label. See also [the handbook entry on color labels](https://handbook.glyphsapp.com/glyph/#glyph/color-label).",
					"minimum": 0,
					"maximum": 11
				},
				{
					"$ref": "#/$defs/color"
				}
			]
		},
		"component": {
			"type": "object",
			"properties": {
				"alignment": {
					"oneOf": [
						{
							"type": "integer",
							"const": -1,
							"description": "Disabled: automatic positioning is disabled."
						},
						{
							"type": "integer",
							"const": 0,
							"description": "Default: automatic positioning follows the normal eligibility rules."
						},
						{
							"type": "integer",
							"const": 1,
							"description": "Forced: automatic positioning is enabled regardless of normal eligibility."
						},
						{
							"type": "integer",
							"const": 3,
							"description": "Horizontal: only the horizontal coordinate is positioned automatically."
						}
					],
					"type": "integer",
					"glyphsNumber": "i8",
					"default": 0,
					"description": "Controls the automatic alignment of the component. `-1`: disabled (no alignment), `0`: default (alignment is based on context), `1`: force alignment (align regardless of context), `3`: horizontal alignment (align horizontally, but allow for manual vertical placement).",
					"glyphsType": "GSComponentAlignment"
				},
				"anchor": {
					"type": "string",
					"description": "The name of the attachment anchor. Set to specify a specific anchor when there are multiple candidates."
				},
				"angle": {
					"type": "number",
					"glyphsNumber": "f64",
					"default": 0,
					"description": "The rotation angle of the component in degrees clockwise.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"attr": {
					"$ref": "#/$defs/shapeAttr",
					"default": {},
					"description": "The attributes of the component.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"keepWeight": {
					"type": "number",
					"glyphsNumber": "f64",
					"default": 0,
					"description": "Unused."
				},
				"locked": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the component is locked."
				},
				"masterId": {
					"type": "string",
					"description": "The ID of the master from which the component is derived.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"orientation": {
					"oneOf": [
						{
							"type": "integer",
							"const": 0,
							"description": "Left: x values are relative to the left edge of the layer box."
						},
						{
							"type": "integer",
							"const": 1,
							"description": "Right: x values are relative to the right edge of the layer box."
						},
						{
							"type": "integer",
							"const": 2,
							"description": "Center: x values are relative to the center of the layer box."
						}
					],
					"type": "integer",
					"default": 0,
					"glyphsNumber": "i8",
					"description": "The orientation of the component.",
					"glyphsCondition": {
						"minVersion": 3
					},
					"glyphsType": "GSElementOrientation"
				},
				"piece": {
					"type": "object",
					"additionalProperties": {
						"oneOf": [
							{
								"type": "number",
								"glyphsNumber": "f64"
							},
							{
								"type": "integer",
								"glyphsNumber": "bool",
								"enum": [
									0,
									1
								]
							}
						]
					},
					"default": {},
					"description": "The Smart Component settings of the component, mapping property names to values."
				},
				"pos": {
					"$ref": "#/$defs/pos",
					"default": [
						0,
						0
					],
					"description": "The position (translation transform) of the component.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"ref": {
					"type": "string",
					"description": "The name of the referenced glyph.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"scale": {
					"$ref": "#/$defs/scale",
					"default": [
						1,
						1
					],
					"description": "The scale transform of the component.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"slant": {
					"$ref": "#/$defs/slant",
					"default": [
						0,
						0
					],
					"description": "The slant transform of the component.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"traverseAnchors": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": true,
					"description": "Whether the component should traverse anchors.",
					"glyphsCondition": {
						"minVersion": 4
					}
				}
			},
			"additionalProperties": false,
			"required": [
				"ref"
			],
			"glyphsType": "GSComponent"
		},
		"customParameter": {
			"type": "object",
			"properties": {
				"disabled": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the custom parameter is disabled."
				},
				"name": {
					"type": "string",
					"description": "The name of the custom parameter."
				},
				"value": {
					"description": "The value of the custom parameter."
				}
			},
			"additionalProperties": false,
			"required": [
				"name",
				"value"
			],
			"glyphsType": "GSCustomParameter"
		},
		"displayStrings": {
			"type": "array",
			"items": {
				"type": "string"
			},
			"glyphsCondition": {
				"packages": false
			}
		},
		"featurePrefix": {
			"type": "object",
			"properties": {
				"automatic": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the code of the feature prefix is generated automatically."
				},
				"disabled": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the feature prefix is disabled."
				},
				"file": {
					"type": "string",
					"description": "The file name of the file containing the code of the feature prefix. The file is located in `DocumentName.glyphspackage/features/FILENAME` where `FILENAME` is this value. The file contents are equivalent to the string defined by the `code` property.",
					"glyphsCondition": {
						"regular": false,
						"package": {
							"minVersion": 4
						}
					}
				},
				"name": {
					"type": "string",
					"examples": [
						"Languagesystems"
					],
					"description": "The name of the feature prefix."
				},
				"notes": {
					"type": "string",
					"default": "",
					"description": "A string serving as a description or comment about the feature prefix."
				}
			},
			"additionalProperties": false,
			"required": [
				"name"
			],
			"glyphsType": "GSFeaturePrefix"
		},
		"feature": {
			"type": "object",
			"properties": {
				"automatic": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the code of the feature is generated automatically."
				},
				"disabled": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": false,
					"description": "Whether the feature is disabled."
				},
				"file": {
					"type": "string",
					"description": "The file name of the file containing the code of the feature. The file is located in `DocumentName.glyphspackage/features/FILENAME` where `FILENAME` is this value. The file contents are equivalent to the string defined by the `code` property.",
					"glyphsCondition": {
						"regular": false,
						"package": {
							"minVersion": 4
						}
					}
				},
				"labels": {
					"type": "array",
					"items": {
						"$ref": "#/$defs/infoValue"
					},
					"default": [],
					"description": "The labels of the feature.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"notes": {
					"type": "string",
					"default": "",
					"description": "A string serving as a description or comment about the feature."
				},
				"tag": {
					"type": "string",
					"minLength": 4,
					"maxLength": 4,
					"examples": [
						"calt"
					],
					"description": "The four-letter tag of the feature.",
					"glyphsCondition": {
						"minVersion": 3
					}
				}
			},
			"additionalProperties": false,
			"required": [
				"file",
				"tag"
			],
			"glyphsType": "GSFeature"
		},
		"fontMaster": {
			"type": "object",
			"properties": {
				"active": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": true,
					"description": "Whether the master is active.",
					"glyphsCondition": {
						"minVersion": 4
					}
				},
				"axesValues": {
					"type": "array",
					"items": {
						"type": "number",
						"glyphsNumber": "f64"
					},
					"default": [],
					"description": "The designspace location of the master.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"customParameters": {
					"type": "array",
					"items": {
						"$ref": "#/$defs/customParameter"
					},
					"default": [],
					"description": "The custom parameters of the master."
				},
				"guides": {
					"type": "array",
					"items": {
						"$ref": "#/$defs/guide"
					},
					"default": [],
					"description": "The global guides of the master.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"iconName": {
					"type": "string",
					"default": "Regular",
					"description": "The name of the icon that represents the master. Generally omitted when equal to `Regular`, or equal to the default icon name of the master (`GSFontMaster.defaultIconName`). For a list of available names, consult `GSFontMaster.iconNames()`."
				},
				"id": {
					"type": "string",
					"description": "The unique identifier of the master."
				},
				"metricValues": {
					"type": "array",
					"items": {
						"$ref": "#/$defs/metricStore"
					},
					"default": [],
					"description": "The metric values of the master.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"name": {
					"type": "string",
					"description": "The name of the master. May be omitted in file format version 1 when equal to `Regular` or the default master name."
				},
				"numberValues": {
					"type": "array",
					"items": {
						"type": "number",
						"glyphsNumber": "f64"
					},
					"default": [],
					"description": "The number values of the master.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"properties": {
					"type": "array",
					"items": {
						"$ref": "#/$defs/infoProperty"
					},
					"default": [],
					"description": "The properties of the master.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"stemValues": {
					"type": "array",
					"items": {
						"type": "number",
						"glyphsNumber": "f64"
					},
					"default": [],
					"description": "The stem values of the master.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"tempData": {
					"$ref": "#/$defs/userData",
					"default": {},
					"description": "Auto-save files only: Temporary data associated with the master.",
					"glyphsCondition": {
						"minVersion": 3
					}
				},
				"userData": {
					"$ref": "#/$defs/userData",
					"default": {},
					"description": "Custom data associated with the master."
				},
				"visible": {
					"type": "integer",
					"glyphsNumber": "bool",
					"enum": [
						0,
						1
					],
					"default": true,
					"description": "Whether the master is visible in the preview."
				}
			},
			"additionalProperties": false,
			"required": [
				"id"
			],
			"glyphsType": "GSFontMaster"
		},
		"glyph": {
			"type": "object",
			"properties": {
